{
  "items": [
    {
      "name": "Polynomial.hasseDeriv_eq_zero_of_lt_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ), p.natDegree < n → (Polynomial.hasseDeriv n) p = 0"
    },
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.hasseDeriv_X",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ), 1 < k → (Polynomial.hasseDeriv k) Polynomial.X = 0"
    },
    {
      "name": "MvPolynomial.monomial_le_degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) {f : MvPolynomial σ R} {m : σ →₀ ℕ},\n  m ∈ f.support → m i ≤ MvPolynomial.degreeOf i f"
    },
    {
      "name": "MvPowerSeries.IsHomogeneous.coeff_eq_zero",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R} {p : ℕ},\n  f.IsHomogeneous p → ∀ {d : σ →₀ ℕ}, Finsupp.degree d ≠ p → (MvPowerSeries.coeff d) f = 0"
    }
  ]
}

{
  "items": [
    {
      "name": "Polynomial.hasseDeriv_eq_zero_of_lt_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ), p.natDegree < n → (Polynomial.hasseDeriv n) p = 0"
    },
    {
      "name": "Polynomial.iterate_derivative_eq_zero_of_degree_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {k : ℕ} {P : Polynomial R}, P.degree < ↑k → (⇑Polynomial.derivative)^[k] P = 0"
    },
    {
      "name": "Polynomial.iterate_derivative_eq_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R} {x : ℕ}, p.natDegree < x → (⇑Polynomial.derivative)^[x] p = 0"
    },
    {
      "name": "Polynomial.hasseDeriv_X",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ), 1 < k → (Polynomial.hasseDeriv k) Polynomial.X = 0"
    },
    {
      "name": "Polynomial.sumIDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.SumIteratedDerivative",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R),\n  Polynomial.sumIDeriv p = ∑ i ∈ Finset.range (p.natDegree + 1), (⇑Polynomial.derivative)^[i] p"
    }
  ]
}

{
  "items": [
    {
      "name": "Polynomial.coeff_X_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n : ℕ), (Polynomial.X * p).coeff (n + 1) = p.coeff n"
    },
    {
      "name": "Polynomial.lcoeff",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "definition",
      "type": "(R : Type u) → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] R"
    },
    {
      "name": "PowerSeries.coeff_X_pow_mul'",
      "module_name": "Mathlib.RingTheory.PowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : PowerSeries R) (n d : ℕ),\n  (PowerSeries.coeff d) (PowerSeries.X ^ n * p) = if n ≤ d then (PowerSeries.coeff (d - n)) p else 0"
    },
    {
      "name": "WittVector.verschiebungFun",
      "module_name": "Mathlib.RingTheory.WittVector.Verschiebung",
      "kind": "definition",
      "type": "{p : ℕ} → {R : Type u_1} → [CommRing R] → WittVector p R → WittVector p R"
    },
    {
      "name": "Polynomial.coeff_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n d : ℕ), (p * Polynomial.X ^ n).coeff (d + n) = p.coeff d"
    }
  ]
}
